import {mountUpdateReady,updateBlocked} from './update-ready.js';
import {BUILD_LABEL,attributesView,vitalsView,abilitiesView,bindDisplay} from './character-display.js';
import {parseSnapshot} from './snapshot.js';
import {loadSnapshot,replaceSnapshot} from './snapshot-store.js';
import {escapeHTML as e,memberCard} from './roster-view.js';
const $=s=>document.querySelector(s);let snapshot=null,snapshotPending=false,snapshotSaving=false;
function render(){if(!snapshot)return;$("#snapshot-loader").open=false;const p=snapshot,c=p.trainer;
 $('#snapshot-content').innerHTML=`<section class="card"><p class="eyebrow">Snapshot · exported ${e(new Date(p.exported_at).toLocaleString())}</p><h1>${e(c.name)}</h1>${!p.hide_owner_stats?vitalsView(c)+attributesView(c.attributes)+abilitiesView(c.ability_slots):''}<p>${e(c.currency.label)} <strong>${c.currency.amount}</strong></section><h2>${e(p.roster_label)}</h2><h3>Active team</h3>${p.roster.filter(r=>r.member.status==='active').map(r=>memberCard(r.member,r.progress)).join('')||'<p>No active members.</p>'}<details class="card"><summary>Boxed members · ${p.roster.filter(r=>r.member.status==='boxed').length}</summary>${p.roster.filter(r=>r.member.status==='boxed').map(r=>memberCard(r.member,r.progress)).join('')}</details><section class="card"><h2>Inventory</h2>${p.inventory.map(i=>`<div class="row"><div><strong>${e(i.item)}</strong><p>${e(i.notes)}</p></div><span class="quantity">× ${i.qty}</span></div>`).join('')||'<p>No items recorded.</p>'}</section>`;
 bindDisplay($('#snapshot-content'),'snapshot:'+p.owner_character_id);
}
const version=document.createElement('p');version.className='build-label';version.textContent=BUILD_LABEL;document.body.append(version);
$('#snapshot-file').onchange=()=>{snapshotPending=!!$('#snapshot-file').files.length;$('#load-snapshot').disabled=!$('#snapshot-file').files.length;$('#snapshot-error').textContent='';};
$('#load-snapshot').onclick=async()=>{const file=$('#snapshot-file').files[0];if(!file)return;snapshotSaving=true;$('#load-snapshot').disabled=true;$('#snapshot-file').disabled=true;$('#snapshot-error').textContent='';try{if(file.size>5*1024*1024)throw Error('Snapshot must be under 5 MB.');const incoming=parseSnapshot(await file.text());await replaceSnapshot(incoming);snapshot=incoming;snapshotPending=false;try{localStorage.setItem('scroll-viewer-mode','1');}catch{}render();$('#snapshot-status').textContent='Latest imported snapshot saved on this device. Read only.';}catch(err){$('#snapshot-error').textContent=err.message;}finally{snapshotSaving=false;$('#load-snapshot').disabled=false;$('#snapshot-file').disabled=false;}};
try{snapshot=await loadSnapshot();render();}catch(e){$('#snapshot-error').textContent=e.message;}
if('serviceWorker'in navigator){try{const registration=await navigator.serviceWorker.register('./sw.js');mountUpdateReady(registration,{isBlocked:()=>updateBlocked({draft:snapshotPending,saving:snapshotSaving}),roots:()=>[document.querySelector('.snapshot-workspace')]});await navigator.serviceWorker.ready;$('#offline-status').textContent='Offline ready · snapshots do not sync automatically.';}catch{$('#offline-status').textContent='Offline caching unavailable. Keep this page online.';}}
